/**
 * Shared Firebase verified-email identity helpers.
 * Ensures only cryptographically verified, non-synthetic email addresses
 * become subscription or student email identity.
 */

const SIMPLE_EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/**
 * Returns true if the given email matches the synthetic fallback generated by
 * historical migration 0006 (`COALESCE(email, id || '@zana.edu.krd')`).
 */
export function isSyntheticPlaceholderEmail(uid: string, email: string): boolean {
  const normalizedUid = (uid || "").trim().toLowerCase();
  const normalizedEmail = (email || "").trim().toLowerCase();
  if (!normalizedUid || !normalizedEmail) return false;
  return normalizedEmail === `${normalizedUid}@zana.edu.krd`;
}

/**
 * Validates basic email format, permits legitimate plus-addressing,
 * and rejects phone numbers (e.g. "+9647...") or malformed dot sequences.
 */
export function isValidEmailSyntax(email: string): boolean {
  const trimmed = (email || "").trim();
  if (!trimmed || trimmed.length > 254 || trimmed.startsWith("+")) return false;
  if (!SIMPLE_EMAIL_REGEX.test(trimmed)) return false;
  const parts = trimmed.split("@");
  if (parts.length !== 2) return false;
  const [localPart, domainPart] = parts;
  if (!localPart || localPart.length > 64 || !domainPart) return false;
  if (
    localPart.startsWith(".") ||
    localPart.endsWith(".") ||
    domainPart.startsWith(".") ||
    domainPart.endsWith(".") ||
    trimmed.includes("..")
  ) {
    return false;
  }
  return true;
}

/**
 * Sanitizes an email candidate passed to checkSubscription or lookup helpers
 * when a UID is known (rejects empty strings, non-emails/phone numbers, and
 * synthetic `<uid>@zana.edu.krd` placeholders).
 */
export function sanitizeVerifiedSubscriptionEmail(
  userId: string,
  candidateEmail?: string | null
): string {
  const normalized = (candidateEmail || "").trim().toLowerCase();
  if (!normalized || !isValidEmailSyntax(normalized)) {
    return "";
  }
  if (isSyntheticPlaceholderEmail(userId, normalized)) {
    return "";
  }
  return normalized;
}

/**
 * Resolves the authoritative verified email from an authenticated user object.
 * Requires `claims.email_verified === true` and rejects synthetic `<uid>@zana.edu.krd`.
 * Never reads client request body or phone_number claims.
 */
export function resolveVerifiedSubscriptionEmail(
  user:
    | {
        uid: string;
        email?: string;
        claims?: {
          email?: unknown;
          email_verified?: unknown;
          [key: string]: unknown;
        };
      }
    | null
    | undefined
): string {
  if (!user || !user.uid) return "";
  if (user.claims?.email_verified !== true) {
    return "";
  }
  const tokenEmail =
    typeof user.claims?.email === "string"
      ? user.claims.email
      : typeof user.email === "string"
        ? user.email
        : "";
  return sanitizeVerifiedSubscriptionEmail(user.uid, tokenEmail);
}
